import {MAX_COLORS,MAX_LIGHTS,LIGHT_META,LIGHT_TYPES,TRACK_META,MATERIAL_STYLES} from './studio-model.js';
import {MOODS} from './model.js';
export function pathValue(s,path){const parts=path.split('.');let value=s;for(let i=0;i<parts.length;i++){if(i===1&&parts[0]==='lights')value=value.find(l=>l.id===Number(parts[i]));else value=value?.[parts[i]];}return value}
export function pathMeta(path){const parts=path.split('.'),last=parts.at(-1);if(last==='cycles')return['Ripetizioni nel loop',1,8,1];if(last==='phase')return['Fase di partenza',0,360,1];if(last==='amplitude'){if(parts[0]==='motions'){const m=TRACK_META[parts[1]];return ['Ampiezza',m[1],m[2],m[3]]}return parts[2]==='orbit'?['Ampiezza orbita',0,180,1]:['Ampiezza pulsazione',0,1,.01]}return LIGHT_META[last]}
export function writePath(s,path,value){const parts=path.split('.');let object=s;for(let i=0;i<parts.length-1;i++){if(i===1&&parts[0]==='lights')object=object.find(l=>l.id===Number(parts[i]));else object=object[parts[i]];}if(object)object[parts.at(-1)]=value}
export function buildPanel(tab,s,h,selectedLight){
 const {slider,section,details,colorField,check,icon}=h;
 const ps=path=>{const [label,min,max,step]=pathMeta(path),v=pathValue(s,path),id='nested-'+path.replaceAll('.','-');return `<div class="param"><div class="param-line"><label for="${id}">${label}</label><input class="number" data-number-path="${path}" type="number" aria-label="${label}: valore" min="${min}" max="${max}" step="${step}" value="${Number(v.toFixed(3))}"></div><input id="${id}" type="range" data-path="${path}" min="${min}" max="${max}" step="${step}" value="${v}" style="--fill:${(v-min)/(max-min)*100}%"></div>`};
 const pc=(path,label)=>`<label class="check"><input type="checkbox" data-path-check="${path}" ${pathValue(s,path)?'checked':''}>${label}</label>`;
 const select=(path,label,items)=>`<label class="field">${label}<select data-path-select="${path}">${items.map(([v,n])=>`<option value="${v}" ${String(pathValue(s,path))===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`;
 const trackPanel=(path,label,rotation=false,color=false)=>{const cycle=(rotation||color)&&pathValue(s,path+'.mode')==='cycle';return details(label,pc(path+'.enabled','Attiva questo movimento')+(rotation||color?select(path+'.mode','Tipo di movimento',[['wave','Oscillazione'],['cycle',rotation?'Giro completo':'Scorrimento continuo']]):'')+(cycle?'':ps(path+'.amplitude'))+ps(path+'.cycles')+ps(path+'.phase')+select(path+'.direction','Verso',[[1,'Normale'],[-1,'Inverso']])+(cycle?'<p class="help">Movimento continuo a velocità uniforme. Le ripetizioni regolano quanti giri compie nel loop.</p>':select(path+'.curve','Curva di movimento',[['sine','Fluida · sinusoidale'],['soft','Morbida · rallenta al centro'],['triangle','Regolare · triangolare']])))};
 if(tab==='shape')return `<button class="quiet full" id="perfect-sphere">${icon('shape')}Sfera perfetta</button>`+section('GEOMETRIA',slider('volume',['Piatta','Volumetrica'])+slider('deform',['Regolare','Organica'])+slider('asymmetry')+slider('twist'))+section('CONTORNO',slider('edge',['Netto','Sfumato']))+details('Dimensioni e inquadratura',['stretchX','stretchY','stretchZ','scale','positionX','positionY','rotateX','rotateY','rotateZ'].map(k=>slider(k)).join(''))+details('Profilo e curvature',['roundness','taper','bendX','bendY','pinch'].map(k=>slider(k)).join(''))+details('Petali, lobi e onde',['lobeAmount','lobes','waves','waveScale'].map(k=>slider(k)).join(''))+details('Vuoto interno · anelli',['hole','holeX','holeY','holeShape','holeAspect','rimRound'].map(k=>slider(k)).join(''))+details('Ritaglio · semilune',['cut','cutX','cutY','cutAspect'].map(k=>slider(k)).join(''));
 if(tab==='material')return `<p class="control-intro">Dalla goccia piena al guscio sottile: la luce attraversa il materiale e viene deviata dalle sue pareti.</p>`+section('PUNTI DI PARTENZA',`<div class="mood-grid">${MATERIAL_STYLES.map((m,i)=>`<button class="mood" data-material="${i}">${m.name}</button>`).join('')}</div>`)+section('TRASPARENZA E INTERNO',slider('transparency',['Opaca','Vedi attraverso'])+slider('hollow',['Pieno','Vuoto'])+slider('wallThickness',['Pellicola sottile','Parete spessa'])+'<p class="help">La vuotezza crea una cavità 3D; lo spessore regola la parete del guscio. Per un materiale limpido usa metallicità 0, scattering 0 e poco assorbimento.</p><button id="test-backlight" class="quiet full">'+icon('sun')+'Prova una luce in orbita</button>')+section('SUPERFICIE',slider('metal',['Dielettrica','Metallica'])+slider('roughness',['Limpida','Satinata'])+slider('gloss'))+details('Traslucenza e diffusione interna',slider('translucency',['Limpida / opaca','Luce diffusa'])+slider('scattering',['Nessuna diffusione','Lattiginosa'])+slider('scatterDirection',['Verso la sorgente','Verso lo sguardo'])+'<p class="help">La trasparenza lascia vedere la sorgente; traslucenza e scattering ne diffondono la luce, come carta, pelle o vetro satinato.</p>')+details('Rifrazione, assorbimento e colore',['refraction','thickness','dispersion','absorption','tintStrength'].map(k=>slider(k)).join('')+'<p class="help">Rifrazione 1: nessuna deviazione. Acqua ≈ 1,33; vetro ≈ 1,50. L’assorbimento cresce con il percorso dentro la materia. Per un interno limpido riduci assorbimento e tinta interna.</p>')+details('Pellicola · bolla di sapone',slider('thinFilm')+slider('filmThickness')+'<p class="help">I colori della pellicola dipendono dallo spessore e dall’angolo della luce. Si combinano con cavità e riflessi.</p>')+section('RIFLESSI E LUCE',slider('iridescence')+slider('emission'))+details('Vernice e riflessi sui bordi',['coat','coatRoughness','fresnel'].map(k=>slider(k)).join(''))+details('Iridescenza e satinatura',['iridShift','iridScale','anisotropy','anisotropyAngle','surfaceTexture'].map(k=>slider(k)).join(''));
 if(tab==='color')return section(`LA TUA PALETTE · ${s.palette.length} / ${MAX_COLORS}`,`<div class="editable-palette">${s.palette.map((c,i)=>`<div class="palette-item"><label class="color-swatch"><input type="color" data-palette="${i}" value="${c}" aria-label="Colore ${i+1} della palette"></label><input class="hex-input" data-palette-hex="${i}" value="${c}" aria-label="Codice esadecimale colore ${i+1}" maxlength="7"><div class="color-actions"><button data-color-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Sposta colore ${i+1} a sinistra">‹</button><button data-color-move="${i}" data-direction="1" ${i===s.palette.length-1?'disabled':''} aria-label="Sposta colore ${i+1} a destra">›</button><button data-color-remove="${i}" ${s.palette.length===1?'disabled':''} aria-label="Rimuovi colore ${i+1}">×</button></div></div>`).join('')}</div><button id="add-color" class="outline full" ${s.palette.length>=MAX_COLORS?'disabled':''}>+ Aggiungi colore</button>`)+section('PALETTE E MOOD',`<div class="mood-grid">${MOODS.slice(0,8).map((m,i)=>moodButton(m,i)).join('')}</div>`+details('Altre 12 palette',`<div class="mood-grid">${MOODS.slice(8).map((m,i)=>moodButton(m,i+8)).join('')}</div>`)+`<button class="quiet full" id="random-palette">${icon('shuffle')}Palette casuale</button>`)+section('COME SI INCONTRANO I COLORI',slider('colorSoftness',['Bande nette','Sfumature'])+slider('gradientScale')+slider('gradientAngle')+slider('gradientOffset'))+section('ALONE',slider('glow'));
 if(tab==='light'){
  const light=s.lights.find(l=>l.id===selectedLight)||s.lights[0],index=light?s.lights.indexOf(light):-1,prefix=light?'lights.'+light.id:'';
  const head=`<div class="panel-toolbar"><span>${s.lights.length} / ${MAX_LIGHTS} luci</span><button id="add-light" class="outline" ${s.lights.length>=MAX_LIGHTS?'disabled':''}>+ Aggiungi</button></div><div class="light-list">${s.lights.map((l,i)=>`<button data-light-select="${l.id}" class="light-chip ${l===light?'selected':''}" style="--light-color:${l.color}" aria-label="Seleziona luce ${i+1}"><i></i>${i+1}${l.z<0?' · dietro':''}</button>`).join('')}</div><button id="show-lights" class="quiet full">${icon('sun')}Mostra comandi sulla tavola</button>`;
  if(!light)return head+'<p class="help">Aggiungi una luce per illuminare la figura.</p>';
  return head+section(`LUCE ${index+1}`,`<div class="panel-toolbar">${pc(prefix+'.enabled','Attiva')}<button data-remove-light="${light.id}" class="quiet danger">Rimuovi</button></div><label class="color-field">Colore della luce<input type="color" data-path-color="${prefix}.color" value="${light.color}"></label>`+select(prefix+'.type','Forma della sorgente',LIGHT_TYPES)+ps(prefix+'.power')+pc(prefix+'.visible','Sorgente visibile nella scena')+'<p class="help">Attiva per vedere la luce direttamente e attraverso i materiali trasparenti. Le sorgenti restano visibili anche nei file esportati.</p>')+section('POSIZIONE NELLO SPAZIO',`<div class="mood-grid"><button data-light-depth="front" class="mood">Davanti alla figura</button><button data-light-depth="back" class="mood">Dietro la figura</button></div>`+['x','y','z'].map(k=>ps(prefix+'.'+k)).join('')+'<p class="help">Trascina il punto per X e Y. Scorri sul punto, o usa Maiusc mentre trascini, per la profondità Z.</p>')+details('Forma e diffusione',(light.type==='spot'?['size','softness']:['circle','ring'].includes(light.type)?['size','softness']:['size','length','roll','softness']).map(k=>ps(prefix+'.'+k)).join('')+(light.type==='spot'?ps(prefix+'.cone'):'')+(light.type==='grid'?ps(prefix+'.grid'):''))+details('Movimento di questa luce',trackPanel(prefix+'.orbit','Orbita',true)+select(prefix+'.orbit.axis','Asse di rotazione',[['x','X · verticale'],['y','Y · orizzontale'],['z','Z · sul piano']])+trackPanel(prefix+'.pulse','Pulsazione di intensità'));
 }
 if(tab==='motion')return `<p class="control-intro">Ogni elemento ha il suo ritmo. Le ripetizioni sono sincronizzate alla durata del loop.</p>`+section('COMANDI RAPIDI',check('animateRotation','Rotazione completa')+check('animateShape','Forma e volume')+check('animateColor','Scorrimento dei colori')+check('animateLight','Orbita di tutte le luci'))+section('DURATA DEL LOOP',slider('motion')+slider('duration')+slider('speed'))+details('Rotazione · 3 assi',['rotateX','rotateY','rotateZ'].map(k=>trackPanel('motions.'+k,TRACK_META[k][0],true)).join(''))+details('Forma · movimenti indipendenti',['volume','deform','twist','waves','hole','cut'].map(k=>trackPanel('motions.'+k,TRACK_META[k][0])).join(''))+details('Posizione e dimensione',['positionX','positionY','scale'].map(k=>trackPanel('motions.'+k,TRACK_META[k][0])).join(''))+details('Colori e materia',['gradientOffset','iridescence','roughness','transparency'].map(k=>trackPanel('motions.'+k,TRACK_META[k][0],false,k==='gradientOffset')).join(''))+details('Ogni singola luce',s.lights.length?s.lights.map((l,i)=>details(`Luce ${i+1}`,trackPanel(`lights.${l.id}.orbit`,'Orbita',true)+select(`lights.${l.id}.orbit.axis`,'Asse',[['x','X'],['y','Y'],['z','Z']])+trackPanel(`lights.${l.id}.pulse`,'Intensità'))).join(''):'<p class="help">Aggiungi una luce nel pannello Luci.</p>')+`<p class="help">Durata effettiva: <strong id="effective-duration">${(s.duration/s.speed).toFixed(1)} s</strong>. L’esportazione a 60 fps calcola ogni fotogramma del movimento.</p>`;
 if(tab==='photo')return `<p class="control-intro">Regola la resa fotografica. Gli effetti vengono conservati anche nei download.</p>`+section('TONI',slider('exposure')+slider('brightness')+slider('contrast')+slider('saturation'))+details('Bilanciamento e gamma',['temperature','photoTint','gamma','blacks','highlights'].map(k=>slider(k)).join(''))+details('Lente e finitura',slider('lensDistortion',['Barilotto','Cuscinetto'])+slider('vignette')+slider('grain')+slider('grainSize'))+check('photoAll','Applica le regolazioni anche allo sfondo')+`<button id="reset-photo" class="quiet full">${icon('reset')}Azzera le regolazioni fotografiche</button>`;
 if(tab==='background')return section('FONDO',`<label class="field">Tipo di sfondo<select id="bg-mode"><option value="solid" ${s.bgMode==='solid'?'selected':''}>Tinta unita</option><option value="gradient" ${s.bgMode==='gradient'?'selected':''}>Gradiente</option><option value="transparent" ${s.bgMode==='transparent'?'selected':''}>Trasparente</option></select></label>${colorField('background','Colore di sfondo')}${s.bgMode==='gradient'?colorField('background2','Secondo colore')+slider('bgAngle'):''}${s.bgMode==='transparent'?'<p class="help">PNG e WebP conservano la trasparenza. JPEG e video usano il colore di sfondo.</p>':''}`)+section('COMPOSIZIONE',slider('scale')+slider('positionX')+slider('positionY'));
 return '';
}
function moodButton(m,i){return `<button class="mood" data-mood="${i}"><span class="mood-dots">${m.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span>${m.name}</button>`}
